mapper.select:
SELECT , CAST(NULL AS varchar) AS time FROM car03_booking a INNER JOIN car01_info b ON a.car03_info_id = b.car01_info_id WHERE 1=1 AND f_trunc(a.car03_start_date) = f_trunc(CAST(#{date} AS timestamp)) AND b.car01_company_id = #{companyId}
AND a.car03_person_id = #{personId}
ORDER BY b.car01_car_nm COLLATE "ko_KR.utf8", a.car03_start_date

SELECT f_booking_car_check( #{bookingId}
                          , #{infoId}
                          , CAST(#{startDate} AS timestamp)
                          , #{startHour}
                          , #{startMin}
                          , #{closeHour}
                          , #{closeMin}
       ) AS car03_check_ok

mapper.delete:
DELETE FROM car03_booking
 WHERE car03_parent_id = #{parentId}
   AND car03_info_id IN (SELECT car01_info_id FROM car01_info WHERE car01_company_id = #{companyId})
